package com.example.inventory;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class Application {
    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

package com.example.inventory;

import java.util.List;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class InventorySyncJob {
    private final WarehouseClient warehouse;
    private final StockRepository stock;
    private final SyncCursorRepository cursor;

    public InventorySyncJob(WarehouseClient warehouse, StockRepository stock, SyncCursorRepository cursor) {
        this.warehouse = warehouse;
        this.stock = stock;
        this.cursor = cursor;
    }

    @Scheduled(fixedRate = 60000)
    public void sync() {
        List<Movement> movements = warehouse.movementsAfter(cursor.load());
        movements.forEach(stock::apply);
        if (!movements.isEmpty()) {
            cursor.save(movements.get(movements.size() - 1).id());
        }
    }
}

package com.example.inventory;

import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class SessionCleanupJob {
    private final SessionRepository sessions;

    public SessionCleanupJob(SessionRepository sessions) {
        this.sessions = sessions;
    }

    @Scheduled(fixedRate = 60000)
    public void purgeExpired() {
        sessions.deleteExpired();
    }
}
